**Critical: SQL injection.** `req.params.id` injected directly into query string. Attacker sends `1 OR 1=1` → dumps all users. Sends `1; DROP TABLE users` → data loss.

**Fix — parameterized query:**

```js
app.get('/api/users/:id', async (req, res) => {
  try {
    const user = await db.query('SELECT * FROM users WHERE id = $1', [req.params.id]);
    if (!user) return res.status(404).json({ error: 'Not found' });
    res.json(user);
  } catch (err) {
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

**Other issues:**

| Issue | Risk | Fix |
|-------|------|-----|
| No auth check | Any user fetches any user's data (IDOR) | Verify `req.user.id === req.params.id` or admin role |
| No input validation | Non-integer id causes DB error or unexpected behavior | Validate `id` is integer before query |
| `SELECT *` | Leaks password hashes, tokens, internal fields | Explicit column list |
| No error handling | DB errors expose stack traces to client | Add try/catch, generic error response |

**Auth + validation added:**

```js
app.get('/api/users/:id', requireAuth, async (req, res) => {
  const id = parseInt(req.params.id, 10);
  if (isNaN(id)) return res.status(400).json({ error: 'Invalid id' });
  if (req.user.id !== id && !req.user.isAdmin) return res.status(403).json({ error: 'Forbidden' });

  try {
    const user = await db.query(
      'SELECT id, name, email, created_at FROM users WHERE id = $1',
      [id]
    );
    if (!user) return res.status(404).json({ error: 'Not found' });
    res.json(user);
  } catch {
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

SQL injection is critical — fix first.
